/**
 * The expansion registry: the catalog of every built-in module (always loaded), the modules whose
 * rules are loaded, and lookups for modes, scenarios and maps.
 *
 * s18 (docs/EXPANSIONS.md §2b): a module's rules load on demand. The catalog (`catalogData.ts`,
 * generated by `pnpm gen:catalog`) names every module, mode, scenario, option, terrain and map,
 * so the setup screen, lobbies and saves work without the rules. `ensureModules(mode or ids)`
 * loads the rules (in the browser: with the module's HUD, board drawer and bots, src/expansions/
 * load.ts); createGame / applyAction / legalActions of a game whose modules are not loaded throw
 * `ModuleNotLoadedError`. Headless code (room server, sim, scripts, tests) installs every module
 * up front (src/expansions/headless.ts).
 *
 * The registry imports no module, so there is no import cycle: modules import core engine files,
 * and they reach the registry only through `installExpansion`.
 */
import { MAPS, type MapDef } from '../maps';
import type { ExpansionId, GameSettings, MapId, ModeId, ScenarioId } from '../types';
import { infoOf } from './catalog';
import { CATALOG } from './catalogData';
import type { ExpansionInfo, ExpansionModule, MapInfo, ModeDef, ScenarioDef } from './types';

/** The base game as a mode: no expansions, the base maps. Always first, always the default. */
export const BASE_MODE: ModeDef = {
  id: 'base',
  name: 'Base',
  blurb: 'Settle, build, trade',
  status: 'ready',
  expansions: [],
  scenarios: [],
  players: { min: 3, max: 8 },
};

/** Thrown when a game needs a module whose rules have not been loaded yet. */
export class ModuleNotLoadedError extends Error {
  constructor(readonly id: ExpansionId) {
    super(
      `expansion "${id}" is not loaded: await ensureModules() before creating or playing ` +
        `a game with it (docs/EXPANSIONS.md §2b)`,
    );
    this.name = 'ModuleNotLoadedError';
  }
}

let catalog: readonly ExpansionInfo[] | null = null;
const loaded = new Map<ExpansionId, ExpansionModule>();
const extra: ExpansionModule[] = [];
/** Registry order, each module's loaded rules in place of its catalog info once loaded. */
let view: readonly ExpansionInfo[] | null = null;

function infos(): readonly ExpansionInfo[] {
  catalog ??= CATALOG.map(infoOf);
  return catalog;
}

function all(): readonly ExpansionInfo[] {
  view ??= [...infos().map((m) => loaded.get(m.id) ?? m), ...extra];
  return view;
}

function changed(): void {
  view = null;
  activeCache = new WeakMap();
}

/**
 * Install a module's rules (the catalog must list it: run `pnpm gen:catalog` after adding one).
 * Installing the same module again does nothing.
 */
export function installExpansion(m: ExpansionModule): void {
  const have = loaded.get(m.id);
  if (have === m) return;
  if (have) throw new Error(`expansion ${m.id} is already installed`);
  if (!infos().some((x) => x.id === m.id)) {
    throw new Error(`expansion ${m.id} is not in the catalog: run pnpm gen:catalog`);
  }
  loaded.set(m.id, m);
  changed();
}

/**
 * Tests only: add a module that is not in the catalog, after the built-in ones (ids must be
 * unique). Returns an undo function. Games created while it is registered keep working only while
 * it stays registered.
 */
export function registerExpansion(m: ExpansionModule): () => void {
  if (expansionById(m.id)) throw new Error(`expansion ${m.id} already registered`);
  extra.push(m);
  changed();
  return () => {
    const i = extra.indexOf(m);
    if (i >= 0) extra.splice(i, 1);
    changed();
  };
}

/** Every known module (catalog info, or its rules once loaded), in registry order. */
export function allExpansions(): readonly ExpansionInfo[] {
  return all();
}

/** Every module whose rules are loaded, in registry order (= the order hooks run in). */
export function allModules(): readonly ExpansionModule[] {
  return all().filter((m): m is ExpansionModule => moduleById(m.id) !== undefined);
}

/** A module's catalog info, or its rules once loaded; undefined for unknown ids. */
export function expansionById(id: ExpansionId): ExpansionInfo | undefined {
  return all().find((m) => m.id === id);
}

/** A module's rules, or undefined when unknown or not loaded yet. */
export function moduleById(id: ExpansionId): ExpansionModule | undefined {
  return loaded.get(id) ?? extra.find((m) => m.id === id);
}

/** A module's rules; throws `ModuleNotLoadedError` when they are not loaded yet. */
export function requireModule(id: ExpansionId): ExpansionModule {
  const m = moduleById(id);
  if (m) return m;
  if (expansionById(id)) throw new ModuleNotLoadedError(id);
  throw new Error(`unknown expansion ${id}`);
}

export function isExpansionId(x: unknown): x is ExpansionId {
  return typeof x === 'string' && expansionById(x) !== undefined;
}

let activeCache = new WeakMap<object, readonly ExpansionModule[]>();
const NONE: readonly ExpansionModule[] = [];

/**
 * Modules active in a game, in settings order. Cached per settings object (settings are shared
 * between the states of a game), so hooks cost nothing in base games. Throws
 * `ModuleNotLoadedError` for a module whose rules are not loaded.
 */
export function activeModules(state: {
  settings: Pick<GameSettings, 'expansions'>;
}): readonly ExpansionModule[] {
  const s = state.settings;
  const ids = s.expansions as readonly ExpansionId[] | undefined;
  if (!ids || ids.length === 0) return NONE;
  let list = activeCache.get(s);
  if (!list) {
    list = ids.map(requireModule);
    activeCache.set(s, list);
  }
  return list;
}

/** Is `id` active in this game? */
export function isActive(state: { settings: Pick<GameSettings, 'expansions'> }, id: ExpansionId) {
  return state.settings.expansions.includes(id);
}

/** The base mode first, then every module's modes in registry order. */
export function listModes(): readonly ModeDef[] {
  return [BASE_MODE, ...all().flatMap((m) => m.modes ?? [])];
}

export function modeById(id: ModeId): ModeDef | undefined {
  return listModes().find((m) => m.id === id);
}

export function allScenarios(): readonly ScenarioDef[] {
  return all().flatMap((m) => m.scenarios ?? []);
}

export function scenarioById(id: ScenarioId): ScenarioDef | undefined {
  return allScenarios().find((s) => s.id === id);
}

/** A base map or a loaded module's map, or undefined. */
export function mapDef(id: MapId): MapDef | undefined {
  if (Object.hasOwn(MAPS, id)) return MAPS[id as keyof typeof MAPS];
  for (const m of all()) {
    const def = moduleById(m.id)?.maps?.find((d) => d.id === id);
    if (def) return def;
  }
  return undefined;
}

/** The catalog info of a module map (loaded or not), or undefined. */
export function expansionMapInfo(id: MapId): MapInfo | undefined {
  for (const m of all()) {
    const info = m.maps?.find((d) => d.id === id);
    if (info) return info;
  }
  return undefined;
}

// ---------------------------------------------------------------------------
// Loading on demand (s18)
// ---------------------------------------------------------------------------

/** What to load: a mode id (its expansions and their requires), or expansion ids (a game's). */
export type ModuleTarget = ModeId | readonly ExpansionId[];

/** The known expansion ids a mode or id list needs, requires included. */
export function modulesOf(target: ModuleTarget): ExpansionId[] {
  const start = typeof target === 'string' ? (modeById(target)?.expansions ?? []) : target;
  const out: ExpansionId[] = [];
  const add = (id: ExpansionId) => {
    const m = expansionById(id);
    if (!m || out.includes(id)) return;
    out.push(id);
    for (const r of m.requires ?? []) add(r);
  };
  for (const id of start) add(id);
  return out;
}

/** Are the rules of everything `target` needs loaded? (The base game: always.) */
export function modulesReady(target: ModuleTarget): boolean {
  return modulesOf(target).every((id) => moduleById(id) !== undefined);
}

let loader: ((id: ExpansionId) => Promise<void>) | null = null;
const pending = new Map<ExpansionId, Promise<void>>();

/**
 * How `ensureModules` loads a module: the loader must install it (`installExpansion`). The
 * browser sets one at boot (src/expansions/load.ts); headless code installs everything instead.
 */
export function setModuleLoader(load: ((id: ExpansionId) => Promise<void>) | null): void {
  loader = load;
}

/**
 * Load the rules of everything a mode or a game's expansion list needs; resolves at once when
 * they are loaded. Must resolve before createGame / applyAction / legalActions for that game.
 * A failed load (network) rejects, and the next call tries again.
 */
export function ensureModules(target: ModuleTarget): Promise<void> {
  const missing = modulesOf(target).filter((id) => moduleById(id) === undefined);
  if (missing.length === 0) return Promise.resolve();
  const load = loader;
  if (!load) return Promise.reject(new ModuleNotLoadedError(missing[0] as ExpansionId));
  return Promise.all(
    missing.map((id) => {
      let p = pending.get(id);
      if (!p) {
        p = load(id).then(
          () => {
            pending.delete(id);
            if (!moduleById(id)) throw new ModuleNotLoadedError(id);
          },
          (e: unknown) => {
            pending.delete(id);
            throw e;
          },
        );
        pending.set(id, p);
      }
      return p;
    }),
  ).then(() => undefined);
}
